<script lang="ts">
import {onMount} from 'svelte';
import {base} from '$app/paths';
import {geoMercator,geoPath} from 'd3-geo';
import type {NeighborhoodGeoJSON} from './analytics';
export let geography:NeighborhoodGeoJSON;
export let selected:string;
let data:any=null, error='', lens='income', tract='27053000101', site='';
const fmt=(v:number|null)=>v==null?'Unavailable':v.toLocaleString('en-US');
onMount(async()=>{try{const r=await fetch(`${base}/data/fp2-geography.json`);if(!r.ok)throw Error('Context source could not load');data=await r.json();}catch(e){error=String(e);}});
$: if(selected) site='';
$: projection=geoMercator().fitExtent([[12,12],[418,408]],geography as any);
$: path=geoPath(projection);
$: sites=(data?.sites??[]).filter((s:any)=>s.neighborhood===selected);
$: current=data?.tracts.features.find((f:any)=>f.properties.geoid===tract)?.properties;
$: currentSite=data?.sites.find((s:any)=>String(s.id)===site);
$: maxIncome=Math.max(1,...(data?.tracts.features??[]).map((f:any)=>f.properties.income??0));
function incomeColor(v:number|null){if(v===null)return '#d3d8d2';const t=Math.sqrt(v/maxIncome);return `rgb(${Math.round(227-200*t)},${Math.round(237-124*t)},${Math.round(221-130*t)})`;}
function choose(e:KeyboardEvent,action:()=>void){if(e.key==='Enter'||e.key===' '){e.preventDefault();action();}}
</script>
<section class="lens" aria-label="Income and traffic at their source geographies"><div class="head"><div><p class="eyebrow">ADDITIONAL CONTEXT / KEEP THE GEOGRAPHY HONEST</p><h2>Income and traffic, at the source scale</h2></div><label>Context layer<select aria-label="Context layer" bind:value={lens}><option value="income">Per-capita income · census tracts</option><option value="traffic">Traffic · 2024 sampled sites</option></select></label></div>
{#if error}<p role="alert">{error}</p>{:else if !data}<p>Loading source geography…</p>{:else}<div class="grid"><svg viewBox="0 0 430 420" role="group" aria-label="Source geography context map"><title>{lens==='income'?'Per-capita income by census tract':'2024 traffic sample locations'}</title>
{#if lens==='income'}{#each data.tracts.features as f}<path d={path(f)??''} fill={incomeColor(f.properties.income)} stroke={tract===f.properties.geoid?'#b44d27':'white'} stroke-width={tract===f.properties.geoid?2:0.5} role="button" tabindex="0" aria-label={`${f.properties.name}: $${fmt(f.properties.income)} per person`} aria-pressed={tract===f.properties.geoid} on:click={()=>tract=f.properties.geoid} on:keydown={e=>choose(e,()=>tract=f.properties.geoid)}><title>{f.properties.name}: ${fmt(f.properties.income)}</title></path>{/each}
{:else}{#each geography.features as f}<path d={path(f as any)??''} fill={f.properties.name===selected?'#e2ebd8':'#f5f6ed'} stroke="#a7baaa" stroke-width="0.5" />{/each}{#each data.sites as s}<circle cx={projection(s.coordinates)?.[0]} cy={projection(s.coordinates)?.[1]} r={s.neighborhood===selected?3.8:1.7} fill={s.neighborhood===selected?'#ac4928':'#547e68'} opacity={s.neighborhood===selected?1:0.45} role="button" tabindex={s.neighborhood===selected?0:-1} aria-label={`Traffic site ${s.id}: ${fmt(s.aadt)} vehicles per day`} on:click={()=>site=String(s.id)} on:keydown={e=>choose(e,()=>site=String(s.id))}><title>{s.name}: {fmt(s.aadt)} vehicles/day (AADT)</title></circle>{/each}{/if}
<path d={path(geography.features.find(f=>f.properties.name===selected) as any)??''} fill="none" stroke="#ac4928" stroke-width="2" pointer-events="none" /></svg>
<div class="content">{#if lens==='income'}<span class="source-tag">ACS B19301 · 2020–2024 · 2024 DOLLARS</span><h3>{current?.name??'Select a tract'}</h3><strong>${fmt(current?.income??null)}</strong><p>Per-capita income · 90% MOE ± ${fmt(current?.moe??null)}</p><label>Select census tract<select aria-label="Select census tract" bind:value={tract}>{#each data.tracts.features as f}<option value={f.properties.geoid}>{f.properties.name}</option>{/each}</select></label><p>121 city census tracts. Darker green means higher income; gray means unavailable. Orange outlines the selected tract and <b>{selected}</b> neighborhood.</p><p>Census tracts and neighborhoods have different boundaries. These income estimates are shown directly, without inventing a neighborhood average or linking them to towing counts at a mismatched scale.</p>{:else}<span class="source-tag">MnDOT · 2024 ANNUAL AVERAGE DAILY TRAFFIC</span><h3>{selected}</h3><strong>{sites.length}</strong><p>matched sample sites in this neighborhood</p><label>Select traffic site<select aria-label="Select traffic site" bind:value={site}><option value="">Choose a site</option>{#each sites as s}<option value={String(s.id)}>{s.name} · #{s.id}</option>{/each}</select></label>{#if currentSite}<p><b>{currentSite.name}: {fmt(currentSite.aadt)} vehicles/day</b><br />Source data-type code: {currentSite.type}. See MnDOT source metadata for code definitions.</p>{/if}<p>1,228 matched sites citywide. Values include measured and modeled annual estimates, not actual traffic during a snow emergency. Site medians are available in the association indicator selector above.</p><p>103 historical sites have no current geometry; 3 have ambiguous or outside-city matches. Those records are excluded, not assigned zero. Sampled sites do not cover all roads.</p>{/if}</div></div>{/if}
</section>
<style>
.lens{max-width:1270px;margin:0 auto 55px;padding:30px;background:#eef2e8;border:1px solid #d4dfd0;color:#173b35}.head{display:flex;justify-content:space-between;gap:30px;align-items:center}.eyebrow{font-size:9px;letter-spacing:.14em;font-weight:700;color:#42644f}.lens h2{font:500 28px 'Space Grotesk',sans-serif;letter-spacing:-.035em;margin:12px 0}.lens label{display:flex;flex-direction:column;gap:8px;font-size:11px;font-weight:600}.lens select{font:12px 'DM Sans',sans-serif;color:#173b35;background:white;border:1px solid #afc2b1;padding:10px;max-width:100%;min-width:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:50px;margin-top:20px}.grid svg{display:block;width:100%;height:420px}.grid svg [role=button]{cursor:pointer}.grid svg [role=button]:focus-visible{outline:3px solid #ad4620}.content{padding:10px 0}.source-tag{font-size:9px;letter-spacing:.1em;color:#49664f}.content h3{font:500 26px 'Space Grotesk',sans-serif;margin:17px 0 5px}.content>strong{font:500 46px 'Space Grotesk',sans-serif}.content p{font-size:12px;line-height:1.8;color:#425b4b}.content label{margin:20px 0}.lens select:focus-visible{outline:3px solid #ad4620;outline-offset:3px}@media(max-width:1000px){.lens{margin:0 4% 40px}.head{align-items:flex-start;flex-direction:column;gap:10px}.grid{gap:25px}}@media(max-width:700px){.lens{padding:20px;margin:0 5% 35px}.grid{grid-template-columns:1fr;gap:5px}.head label{width:100%}.lens h2{font-size:25px}.grid svg{height:360px}.content>strong{font-size:39px}}
</style>
